where g.levelno <= 3 and g.visible='T' and ((g.name like 'Head%' and COALESCE(h.levelno,4) in (4,3))) and g.name in(select parent from axpages where pagetype is not null and visible ='T') union all select a.caption,a.name,a.ordno,case when a.pagetype is null then 't' else 'f' end isparent from axpages a left join axpages b on a.parent =b.name where a.visible ='T' and a.pagetype is not null)a order by ordno
